             query = query.Where(e => e.Zeitpunkt < toExclusive);
         }

+        if (venueId is not null)
+        {
+            query = query.Where(e => e.VenueId == venueId.Value);
+        }
+
         return await query
             .OrderBy(e => e.Zeitpunkt)
