11	    {
12	        IQueryable<Event> query = dbContext.Events;
13	
14	        if (from is not null)
15	        {
16	            var fromStart = from.Value.ToDateTime(TimeOnly.MinValue);
17	            query = query.Where(e => e.Zeitpunkt >= fromStart);
18	        }
19	
20	        if (to is not null)
21	        {
22	            var toExclusive = to.Value == DateOnly.MaxValue
23	                ? DateTime.MaxValue
24	                : to.Value.AddDays(1).ToDateTime(TimeOnly.MinValue);
25	            query = query.Where(e => e.Zeitpunkt < toExclusive);
26	        }
27	
28	        if (venueId is not null)
29	        {
30	            query = query.Where(e => e.VenueId == venueId.Value);
31	        }
32	
33	        return await query
34	            .OrderBy(e => e.Zeitpunkt)
35	            .Select(e => new EventListItemDto(e.Id, e.Titel, e.Venue!.Name, e.Zeitpunkt))
36	            .ToListAsync();
37	    }
