39	    public async Task<List<VenueListItemDto>> GetVenuesAsync()
40	    {
41	        return await dbContext.Venues
42	            .OrderBy(v => v.Name)
43	            .Select(v => new VenueListItemDto(v.Id, v.Name))
44	            .ToListAsync();
45	    }
