21	})
22	export class EventListPage {
23	  private readonly eventService = inject(EventService);
24	  private readonly venueService = inject(VenueService);
25	
26	  protected readonly events = signal<EventListItem[] | null>(null);
27	  protected readonly loadError = signal(false);
28	  protected readonly placeholderCount = 5;
29	  protected readonly placeholders = Array.from({ length: this.placeholderCount });
30	
31	  protected readonly von = signal<string | null>(null);
32	  protected readonly bis = signal<string | null>(null);
33	  protected readonly venueId = signal<string | null>(null);
34	  protected readonly venues = signal<VenueListItem[]>([]);
35	
36	  protected readonly hasActiveFilter = computed(() => this.von() !== null || this.bis() !== null || this.venueId() !== null);
37	
38	  protected readonly activeFilterChips = computed<ActiveFilterChip[]>(() => {
39	    const chips: ActiveFilterChip[] = [];
40	
41	    const von = this.von();
42	    if (von !== null) {
43	      chips.push({ key: 'von', label: `Von ${this.formatDate(von)}`, onClear: () => this.von.set(null) });
44	    }
45	
46	    const bis = this.bis();
47	    if (bis !== null) {
48	      chips.push({ key: 'bis', label: `Bis ${this.formatDate(bis)}`, onClear: () => this.bis.set(null) });
49	    }
50	
51	    const venueId = this.venueId();
52	    if (venueId !== null) {
53	      const venueName = this.venues().find((venue) => venue.id === venueId)?.name ?? venueId;
54	      chips.push({ key: 'venue', label: venueName, onClear: () => this.venueId.set(null) });
55	    }
56	
57	    return chips;
58	  });
59	
60	  constructor() {
61	    this.venueService.getVenues().subscribe((venues) => this.venues.set(venues));
62	
63	    effect((onCleanup) => {
64	      const from = this.von() ?? undefined;
65	      const to = this.bis() ?? undefined;
66	      const venueId = this.venueId() ?? undefined;
67	
68	      this.events.set(null);
69	      this.loadError.set(false);
70	
71	      const subscription = this.eventService.getEvents({ from, to, venueId }).subscribe({
72	        next: (events) => this.events.set(events),
73	        error: () => this.loadError.set(true)
74	      });
75	
76	      onCleanup(() => subscription.unsubscribe());
77	    });
78	  }
79	
80	  protected resetFilters(): void {
81	    this.von.set(null);
82	    this.bis.set(null);
83	    this.venueId.set(null);
84	  }
85	
86	  private formatDate(isoDate: string): string {
87	    const [year, month, day] = isoDate.split('-');
88	    return `${day}.${month}.${year}`;
89	  }
90	}
